control.onCreate:
sender.style.overflow = "auto";
sender.innerHTML = `
<style>
  .epage-overview {
    color: #23243d;
    font: 16px/1.6 system-ui, "Segoe UI", sans-serif;
    text-align: left;
    white-space: normal;
    overflow-wrap: break-word;
  }
  .epage-overview * { box-sizing: border-box; }
  .epage-overview p { margin: 0; }
  .epage-overview h1, .epage-overview h2, .epage-overview h3 {
    margin: 0;
    line-height: 1.15;
  }
  .epage-overview .overview-wrap {
    width: min(100%, 1120px);
    margin-inline: auto;
    padding-inline: clamp(18px, 5vw, 44px);
  }
  .epage-overview .overview-hero {
    padding-block: clamp(32px, 5vw, 56px);
    background: linear-gradient(120deg, #26234c, #423b83);
    color: #fff;
  }
  .epage-overview h1 {
    max-width: 19ch;
    font-size: clamp(32px, 5vw, 56px);
    letter-spacing: -.04em;
  }
  .epage-overview .overview-hero p {
    max-width: 62ch;
    margin-block: 20px 26px;
    color: #ebe8ff;
    font-size: clamp(16px, 2vw, 19px);
  }
  .epage-overview .overview-link {
    display: inline-block;
    padding: 10px 18px;
    border-radius: 8px;
    background: #fff;
    color: #342d72;
    font-weight: 650;
    text-decoration: none;
  }
  .epage-overview .overview-link:hover { background: #e9e5ff; }
  .epage-overview .overview-link:focus-visible {
    outline: 2px solid #fff;
    outline-offset: 4px;
  }
  .epage-overview .overview-section { padding-block: clamp(28px, 5vw, 56px); }
  .epage-overview h2 { font-size: clamp(24px, 4vw, 34px); }
  .epage-overview h3 { font-size: 19px; }
  .epage-overview .overview-steps {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
    gap: 16px;
    margin-top: 20px;
  }
  .epage-overview .overview-step {
    padding: 22px;
    border: 1px solid #e2dff2;
    border-radius: 12px;
    background: #fff;
  }
  .epage-overview .overview-step p,
  .epage-overview .overview-details p { margin-top: 10px; color: #4d4c64; }
  .epage-overview .overview-details {
    border-top: 1px solid #e2dff2;
  }
  .epage-overview code { color: #403583; }
</style>
<main class="epage-overview" lang="en">
  <section class="overview-hero">
    <div class="overview-wrap">
      <h1>Build web applications with ePage Studio</h1>
      <p>Design pages visually, write JavaScript for browser interactions and server-side logic, and publish your project with eServer. This website is built with ePage.</p>
      <a class="overview-link" href="./features?v=task-set">Explore features</a>
    </div>
  </section>
  <div class="overview-wrap">
    <section class="overview-section" aria-labelledby="overview-workflow">
      <h2 id="overview-workflow">How ePage works</h2>
      <div class="overview-steps">
        <article class="overview-step">
          <h3>Design in ePage Studio</h3>
          <p>Arrange controls visually, adjust their properties, and use layouts and layers to organize each page.</p>
        </article>
        <article class="overview-step">
          <h3>Add application logic</h3>
          <p>Use JavaScript for control events. When an action needs eServer, a Task Set groups request preparation, server logic, and the browser response in one named operation.</p>
        </article>
        <article class="overview-step">
          <h3>Publish with eServer</h3>
          <p>Register your project directory in eServer. It reads your page definitions and serves the application over HTTP or HTTPS.</p>
        </article>
      </div>
    </section>
    <section class="overview-section overview-details" aria-labelledby="overview-task-set">
      <h2 id="overview-task-set">Connect a page to eServer with Task Set</h2>
      <p>When a visitor submits a form, a Task Set can read the input in the browser, validate and process it on eServer, then display the result in the page. All three scripts are stored with the page.</p>
      <p><a href="./tutorials?v=project-admin#task-set-tutorial">Try a Task Set and read the three scripts</a></p>
    </section>
    <section class="overview-section overview-details" aria-labelledby="overview-files">
      <h2 id="overview-files">How a project is organized</h2>
      <p>Each page has its own directory. Its <code>page.xml</code> stores the visual controls and the page's client-side and server-side code. Images and other page assets can live beside that file. At the project root, <code>project.xml</code> lists the pages and resources.</p>
    </section>
  </div>
</main>`;
